// Des: Cloud vendor pool: configured stores and SQL vendors
// Flo: read endpoint + key file per vendor in config order > build the client > hand the flow a list with caps in bytes
// I/O: Ctx (config, key folder) + transport (caller) > Hand (stores and databases); a vendor without endpoint or key is skipped, never an error
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const cfgz = @import("cf-conf-load.zig"); const b2zz = @import("sy-clou-b2zz.zig"); const r2zz = @import("sy-clou-r2zz.zig"); const tigr = @import("sy-clou-tigr.zig"); const flow = @import("ru-clou-flow.zig"); const base = @import("nt-vend-base.zig");
const CF = .{ .keyz = 4096, .gibi = 1 << 30, .mebi = 1 << 20 };
pub const Hand = struct { stos: []flow.Vend, sqls: []flow.Vsqd };
pub fn keyzText(ctx2: *const ctx3.Ctxz, keyd: []const u8, name: []const u8) ?[]const u8 { const path = std.fs.path.join(ctx2.allo, &.{ keyd, name }) catch return null; const raws = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, path, ctx2.allo, .limited(CF.keyz)) catch return null; const tex2 = std.mem.trim(u8, raws, " \t\r\n"); return if (tex2.len == 0) null else tex2; }
pub fn endpOfzz(conf: cfgz.Conf, name: []const u8) cfgz.Endp { if (std.mem.eql(u8, name, "b2zz")) return conf.clou_endp.b2zz; if (std.mem.eql(u8, name, "r2zz")) return conf.clou_endp.r2zz; if (std.mem.eql(u8, name, "tigr")) return conf.clou_endp.tigr; if (std.mem.eql(u8, name, "turs")) return conf.clou_endp.turs; if (std.mem.eql(u8, name, "neon")) return conf.clou_endp.neon; return conf.clou_endp.tidb; }
pub fn capzOfzz(conf: cfgz.Conf, name: []const u8) u64 { const gibz: f64 = if (std.mem.eql(u8, name, "b2zz")) conf.clou_capz_gbyt.b2zz else if (std.mem.eql(u8, name, "r2zz")) conf.clou_capz_gbyt.r2zz else conf.clou_capz_gbyt.tigr; return @intFromFloat(@max(1, gibz * CF.gibi)); }
pub fn capqOfzz(conf: cfgz.Conf, name: []const u8) u64 { const mebz: u64 = if (std.mem.eql(u8, name, "turs")) conf.clou_sqlz_capz_mbyt.turs else if (std.mem.eql(u8, name, "neon")) conf.clou_sqlz_capz_mbyt.neon else conf.clou_sqlz_capz_mbyt.tidb; return mebz * CF.mebi; }
pub fn handMake(ctx2: *const ctx3.Ctxz, send: base.Send, keyd: []const u8) !Hand { var stos: std.ArrayList(flow.Vend) = .empty; for (ctx2.conf.clou_stor_orde) |name| { const end2 = endpOfzz(ctx2.conf, name); if (end2.bukt.len == 0) continue; const ktzz = keyzText(ctx2, keyd, std.fmt.allocPrint(ctx2.allo, "{s}.key", .{name}) catch continue) orelse continue; const pair = stor.keyzPair(ktzz) catch continue; const cred = (if (std.mem.eql(u8, name, "b2zz")) b2zz.credMake(ctx2.allo, end2, pair) else if (std.mem.eql(u8, name, "r2zz")) r2zz.credMake(ctx2.allo, end2, pair) else tigr.credMake(ctx2.allo, end2, pair)) catch continue; const s3zz = try ctx2.allo.create(stor.S3zz); s3zz.* = .{ .cred = cred, .bukt = end2.bukt, .send = send, .gpaz = ctx2.init.gpa }; try stos.append(ctx2.allo, .{ .name = name, .store = s3zz.store(), .capb = capzOfzz(ctx2.conf, name) }); }
var sqls: std.ArrayList(flow.Vsqd) = .empty; for (ctx2.conf.clou_sqlz_orde) |name| { const end2 = endpOfzz(ctx2.conf, name); if (end2.host.len == 0) continue; const ktzz = keyzText(ctx2, keyd, std.fmt.allocPrint(ctx2.allo, "{s}.key", .{name}) catch continue) orelse continue; const kind: sqlz.Kind = if (std.mem.eql(u8, name, "turs")) .turs else if (std.mem.eql(u8, name, "neon")) .neon else .tidb; const netz = try ctx2.allo.create(sqlz.Netz); netz.* = .{ .kind = kind, .end2 = end2, .key2 = ktzz, .send = send, .gpaz = ctx2.init.gpa }; try sqls.append(ctx2.allo, .{ .name = name, .sql2 = netz.sql2(), .capb = capqOfzz(ctx2.conf, name) }); } return .{ .stos = try stos.toOwnedSlice(ctx2.allo), .sqls = try sqls.toOwnedSlice(ctx2.allo) }; }
